-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Keeps the current step and arrow in sync with the published guidance.

local nav = APR.navigation
local Shared = APR.navigation._helpers
local ActionPending = Shared.ActionPending
local ActionUsable = Shared.ActionUsable
local CaptureContext = Shared.CaptureContext
local ContextCurrent = Shared.ContextCurrent
local DepartureAllowed = Shared.DepartureAllowed
local Distance = Shared.Distance
local Enabled = Shared.Enabled
local HasWalkingPath = Shared.HasWalkingPath
local L = Shared.L
local NavigationText = Shared.NavigationText
local Now = Shared.Now
local Position = Shared.Position
local SameLocationFields = Shared.SameLocationFields
local TerrainRequired = Shared.TerrainRequired
local WalkingProvider = Shared.WalkingProvider

function nav:BeginGuidanceMeasurement(source)
    self.guidanceMeasurement = debugprofilestop
            and {
                source = source,
                startedAt = debugprofilestop(),
                previousGeneration = self.generation,
                previousContext = source == "service" and self.context or nil,
            }
        or nil
end--[[APR_DIAG]]; nav.BeginGuidanceMeasurement = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:25:nav:BeginGuidanceMeasurement#1", nav.BeginGuidanceMeasurement)--[[/APR_DIAG]]

function nav:MarkGuidanceSurface(surface, step)
    local sample = self.guidanceMeasurement
    if
        not sample
        or sample.cancelled
        or sample[surface]
        or self.generation == sample.previousGeneration
        or (sample.source == "service" and (not self.context or not self.context.service or self.context == sample.previousContext))
        or step ~= self:GetActiveStep()
        or not HasWalkingPath(step)
    then
        return
    end
    if surface == "Published" then
        sample.path, sample.generation = step.path, self.generation
        sample.approachOnly, sample.residualYards = step.approachOnly, step.residualYards
        sample.previousContext = nil
    elseif sample.path ~= step.path then
        return
    end
    sample[surface] = debugprofilestop() - sample.startedAt
    if APR.RecordPerformanceDuration then
        APR:RecordPerformanceDuration("NavigationGuidance" .. surface, sample[surface])
    end
end--[[APR_DIAG]]; nav.MarkGuidanceSurface = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:36:nav:MarkGuidanceSurface#2", nav.MarkGuidanceSurface)--[[/APR_DIAG]]

function nav:GetGuidanceTarget()
    local step = self:GetActiveStep()
    if step and step.pathArrowUnavailable then return end
    if HasWalkingPath(step) then return step.pathAimPoint or step.path[step.pathAimIndex or step.pathCursor or 2] end
    if step then return step.kind == "walk" and step.to or step.from end
end--[[APR_DIAG]]; nav.GetGuidanceTarget = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:62:nav:GetGuidanceTarget#3", nav.GetGuidanceTarget)--[[/APR_DIAG]]

function nav:BlocksDirectGuidance()
    if self:IsNavigating() then return false end
    if self.state == "planning" and self.search and self.search.request and self.search.request.deferDirect then
        return true
    end
    if self.state == "waiting_data" and self.reason == "terrain_coverage" then return true end
    if
        self.state == "ready"
        and (self.reason == "step_changed" or self.reason == "service_cancelled" or self.reason == "service_started")
    then
        local provider = WalkingProvider()
        if provider and provider.RequiresWalkingProof then return true end
    end
    local service = APR.Services and APR.Services:GetStep()
    return (service and (service._mapWaypoint == true or service.serviceWaypoint == true))
        or (self.state ~= "ready" and TerrainRequired(self.start, self.destination))
end--[[APR_DIAG]]; nav.BlocksDirectGuidance = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:68:nav:BlocksDirectGuidance#4", nav.BlocksDirectGuidance)--[[/APR_DIAG]]

function nav:CaptureRetainedArrow(position)
    if self.retainedArrow and self.retainedArrow.serviceWaypoint then
        local waypoint = self:GetRetainedArrow()
        local data = APR.NavigationData
        if
            waypoint
            and position
            and position.instanceID == waypoint.instanceID
            and data:CanWalk(position, waypoint.inputs.step.target) == true
        then
            return waypoint
        end
        return
    end
    local arrow = APR.Arrow
    if not arrow or not arrow.Active or type(arrow.x) ~= "number" or type(arrow.y) ~= "number" then return end
    local active = self:GetActiveStep()
    local displayAction = (self.retainedArrow and self.retainedArrow.displayAction)
        or (active and active.sourceFree and active.action)
    if HasWalkingPath(active) then return end
    if arrow.x == 0 and not self.retainedArrow and not self:IsNavigating() then return end
    if not ContextCurrent(self._routedStepContext) or not self:IsObjectiveCurrent(self._routeInputs) then return end
    local world = (self.retainedArrow and self.retainedArrow.instanceID)
        or (active and active.instanceID)
        or (self.destination and self.destination.instanceID)
        or (self.start and self.start.instanceID)
    if not position or position.instanceID ~= world then return end
    -- This target is display-only. Cancelling an obsolete itinerary must still
    -- remove its actions and arrival checks while its replacement is computed.
    return {
        Coord = not displayAction and { x = arrow.x, y = arrow.y } or nil,
        displayAction = displayAction and { type = displayAction.type, data = displayAction.data } or nil,
        uiMapID = (self.retainedArrow and self.retainedArrow.uiMapID)
            or (active and active.uiMapID)
            or (self.destination and self.destination.uiMapID),
        label = (self.retainedArrow and self.retainedArrow.label) or (active and active.label),
        id = (self.retainedArrow and self.retainedArrow.id) or (active and active.id),
        instanceID = position.instanceID,
        context = self._routedStepContext,
        inputs = self._routeInputs,
    }
end--[[APR_DIAG]]; nav.CaptureRetainedArrow = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:83:nav:CaptureRetainedArrow#5", nav.CaptureRetainedArrow)--[[/APR_DIAG]]

function nav:GetRetainedArrow()
    local target = self.retainedArrow
    if
        target
        and Enabled()
        and (not target.serviceWaypoint or not self.worldLoading)
        and not (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player"))
        and ContextCurrent(target.context)
        and self:IsObjectiveCurrent(target.inputs)
    then
        return target
    end
end--[[APR_DIAG]]; nav.GetRetainedArrow = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:126:nav:GetRetainedArrow#6", nav.GetRetainedArrow)--[[/APR_DIAG]]

function nav:ShowServiceWaypoint(step, context, position)
    local target = step.target
    local data = APR.NavigationData
    if position and position.instanceID == target.instanceID and data:CanWalk(position, target) == true then
        -- Publish the destination bearing without creating an arrival check or a walking segment.
        self.retainedArrow = {
            Coord = step.Coord,
            uiMapID = target.uiMapID,
            instanceID = target.instanceID,
            label = APR.Services:GetLabel(),
            context = context,
            inputs = { step = step },
            serviceWaypoint = true,
        }
    end
    self:Notify()
end--[[APR_DIAG]]; nav.ShowServiceWaypoint = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:140:nav:ShowServiceWaypoint#7", nav.ShowServiceWaypoint)--[[/APR_DIAG]]

function nav:Notify()
    local step = self:GetActiveStep()
    if self.state == "guiding" and step and self._routeInputs then self._routeInputs.hadGuidance = true end
    if self.waypointJourney then self:SaveWaypointJourney() end
    self:MarkGuidanceSurface("Published", step)
    if APR.Arrow then
        APR.Arrow.currentStep = 0
        APR.Arrow:SetCoord()
        if
            APR.Arrow.Active
            and APR.Arrow.UpdatePosition
            and (HasWalkingPath(self:GetActiveStep()) or self.retainedArrow and self.retainedArrow.serviceWaypoint)
        then
            APR.Arrow:UpdatePosition()
        end
    end
    if APR.event and APR.event.QueueStepRefresh then APR.event:QueueStepRefresh() end
    if APR.SendMessage then APR:SendMessage("APR_MAP_UPDATE") end
    self:Render()
end--[[APR_DIAG]]; nav.Notify = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:158:nav:Notify#8", nav.Notify)--[[/APR_DIAG]]

function nav:RefreshStepForNavigation()
    if APR.UpdateStep then APR:UpdateStep() end
end--[[APR_DIAG]]; nav.RefreshStepForNavigation = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:179:nav:RefreshStepForNavigation#9", nav.RefreshStepForNavigation)--[[/APR_DIAG]]

function nav:MarkRouteReady(forceRefresh, arrivedPosition, walkingEndpoint)
    local service = APR.Services and APR.Services:GetStep()
    if service then
        if self.waypointApproach then return end
        -- A verified walking corridor can resolve the arrival floor when the
        -- live position has no altitude and several floors share that XY.
        local point = arrivedPosition or Position()
        local target = service.target
        if walkingEndpoint
            and SameLocationFields(walkingEndpoint, target, APR.NavigationConstants.Navigation.LOCATION_FIELDS)
        then
            target = walkingEndpoint
        end
        if APR.NavigationData:IsServiceArrival(point, target) then
            APR.Services:Cancel()
        else
            -- Exhausting guidance is not proof of a legal direct approach.
            -- Re-enter the library planner so mandatory passages remain enforced.
            self:Cancel("replan")
            self.dirty = true
            self:RequestUpdate()
        end
        return
    end
    local unlock = APR.GetNavigationUnlockStep and APR:GetNavigationUnlockStep()
    if unlock and unlock.unlockAction and (unlock.unlockAction.target or unlock.unlockAction.positionOptional) then
        local action = unlock.unlockAction
        self.queue, self.cursor =
            {
                {
                    kind = "unlock",
                    id = "unlock:" .. self.generation,
                    from = action.target,
                    to = action.target,
                    Coord = unlock.Coord,
                    label = action.label,
                    generated = true,
                    mandatory = true,
                    sourceFree = action.target == nil,
                },
            }, 1
        local useActions = action.useActions or {}
        if #useActions == 1 then self.queue[1].action = { type = useActions[1].type, data = useActions[1].id } end
        self.context = CaptureContext()
        self._routedStepContext = self.context
        self.state, APR.IsInRouteZone, self.dirty = "guiding", false, false
        self:Notify()
        return
    end
    local inputs, destination, start = self._routeInputs, self.destination, self.start
    self.dirty = false
    if not forceRefresh and self.state == "ready" and ContextCurrent(self._routedStepContext) then
        -- A background search confirmed the same direct journey. Its result
        -- does not change the arrow, quest rows or map preview.
        self.recomputeKeepingDirect, self.reason = nil, nil
        APR.IsInRouteZone = true
        return
    end
    -- Publish the authored target without hiding the previous arrow between
    -- clearing temporary guidance and assigning the replacement coordinates.
    self:Cancel("local", true)
    self.state, APR.IsInRouteZone, self._lastReady = "ready", true, Now()
    self._routedStepContext = CaptureContext()
    self.context, self._routeInputs, self.destination, self.start = self._routedStepContext, inputs, destination, start
    self:Notify()
end--[[APR_DIAG]]; nav.MarkRouteReady = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:183:nav:MarkRouteReady#10", nav.MarkRouteReady)--[[/APR_DIAG]]

function nav:Render()
    if self.RefreshActivity then self:RefreshActivity() end
    if self.worldLoading then return end
    local ui = APR.currentStep
    if not ui then return end
    if not Enabled() or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then
        if self.state ~= "ready" then self:Cancel("inactive") end
        return
    end
    if self:IsNavigating() and not ContextCurrent(self.context) then
        self:Cancel("step_changed")
        return
    end
    local step = self:GetActiveStep()
    local action = self:IsNavigating() and step and step.action
    if APR.Services and APR.Services:GetStep() and ui.RefreshServiceProgress then ui:RefreshServiceProgress() end
    local position = action and Position()
    local actionReady = action
            and not ActionPending(step)
            and DepartureAllowed(step, position) == true
            and ActionUsable(action) == true
            and (step.sourceFree or Distance(position, step.from) <= 30)
        or false
    local hostile = step and step.kind == "walk" and step.path and step.path.lastHostileIndex
        and (step.pathCursor or 2) <= step.path.lastHostileIndex
    if self._renderedState ~= self.state or self._renderedStep ~= step or self._renderedActionReady ~= actionReady
        or self._renderedHostile ~= hostile then
        self:ClearNavigationUiLines()
    end
    self._renderedState, self._renderedStep, self._renderedActionReady = self.state, step, actionReady
    self._renderedHostile = hostile
    if self:IsNavigating() and step then
        -- The service destination already has its own row. A final walking
        -- instruction with the same label adds no information to that row.
        local service = APR.Services and APR.Services:GetStep()
        local duplicateDestination = service
            and step.kind == "walk"
            and not action
            and step.label == APR.Services:GetLabel()
        if not duplicateDestination then
            ui:AddQuestSteps(self.NavigationStepKey, step.label, step.id or 0, nil, true, false)
            if actionReady then
                ui:AddStepButton(self.NavigationStepKey .. "-" .. tostring(step.id), action.data, action.type)
            end
        end
        if hostile then
            local faction = step.path[step.path.lastHostileIndex].terrainFaction
            local enemy = faction == "Alliance" and FACTION_HORDE or faction == "Horde" and FACTION_ALLIANCE
            local warning = enemy and FACTION_CONTROLLED_TERRITORY
                and string.format(FACTION_CONTROLLED_TERRITORY, enemy) or FACTION_STANDING_LABEL2
            if warning then
                ui:AddQuestSteps(self.NavigationStepKey .. "-hostile", warning, 0, nil, true, false, self.ErrorTextColor)
            end
        end
        if (hostile or not duplicateDestination) and ui.AddQuestDivider then
            ui:AddQuestDivider(self.NavigationDividerStepKey)
        end
    elseif self.state == "no_path" then
        local text = APR.NavigationAdapter
                and APR.NavigationAdapter.GetBlockedRouteText
                and APR.NavigationAdapter:GetBlockedRouteText(self.blockers, true)
            or NavigationText("PATH_NOT_FOUND")
        if self.unlockMissingText then text = text .. "\n\n" .. self.unlockMissingText end
        if self.waypointApproach then text = text .. "\n" .. self.waypointApproach.label end
        ui:AddQuestSteps(
            self.ErrorStepKey,
            text,
            self.destination and self.destination.uiMapID or 0,
            nil,
            true,
            false,
            self.ErrorTextColor
        )
        if ui.AddQuestDivider then ui:AddQuestDivider(self.NavigationDividerStepKey) end
    elseif self.state == "instance" and not APR.IsInRouteZone then
        -- GetInstanceInfo can identify a dungeon while UnitPosition is
        -- restricted. An exterior objective needs an actual exit, not a
        -- permanent loading message or an arrow based on invented coordinates.
        local name = self.instanceContext and self.instanceContext.instanceName
        local text = string.format(L["LEAVE_INSTANCE"], name and name ~= "" and name or NavigationText("UNKNOWN"))
        ui:AddQuestSteps(self.NavigationStepKey, text, 0, nil, true, false)
        if ui.AddQuestDivider then ui:AddQuestDivider(self.NavigationDividerStepKey) end
    elseif self.state == "waiting_data" or self.state == "planning" then
        local text
        if self.state == "waiting_data" then
            text = L["NAVIGATION_WAITING"]
        elseif not (self._routeInputs and self._routeInputs.hadGuidance) then
            text = L["NAVIGATION_CALCULATING"]
        end
        if self.waypointApproach and self.waypointApproach.reached then
            local label = self.waypointApproach.label
            text = text and (text .. "\n" .. label) or label
        end
        local blocked = self.blockers and #self.blockers > 0
        if blocked and APR.NavigationAdapter and APR.NavigationAdapter.GetBlockedRouteText then
            local details = APR.NavigationAdapter:GetBlockedRouteText(self.blockers, true)
            text = text and (text .. "\n\n" .. details) or details
        end
        if not text then return end
        ui:AddQuestSteps(self.NavigationStepKey, text, 0, nil, true, false)
        if blocked and ui.AddQuestDivider then ui:AddQuestDivider(self.NavigationDividerStepKey) end
    end
end--[[APR_DIAG]]; nav.Render = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:244:nav:Render#11", nav.Render)--[[/APR_DIAG]]

function nav:GuideRestrictedInstance(context, step, start, goal, map)
    if start or not APR.GetNavigationPlayerContext then return false end
    local observed = APR:GetNavigationPlayerContext()
    if not observed or not observed.isInstance or observed.coordinatesAvailable then return false end
    local inside = (goal and goal.instanceID == observed.instanceID)
        or (map and observed.uiMapID == map)
        or (APR.IsInScenarioStep and APR:IsInScenarioStep(step, map))
        or false
    self:Cancel("instance_position_unavailable")
    self.state, self.reason, self.context, self._routedStepContext =
        "instance", "coordinates_unavailable", context, context
    self.instanceContext, self.start, self.destination, self.dirty = observed, nil, goal, false
    APR.IsInRouteZone, self.showOutOfZoneStepContent = inside, inside
    self:Notify()
    return true
end--[[APR_DIAG]]; nav.GuideRestrictedInstance = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:333:nav:GuideRestrictedInstance#12", nav.GuideRestrictedInstance)--[[/APR_DIAG]]

function nav:SearchFailed(blockers, missingCoverage)
    local unresolvedSurface = self.search and self.search.unresolvedSurface
    local surfaceOnly = unresolvedSurface and not self.search.otherDataPending
    local unresolvedStart = unresolvedSurface and self.search.unresolvedStartSurface
    self:CancelLocalPath()
    self.search, self._searchTimer = nil, nil
    if self.travelPrefix and self:IsItineraryValid() then return end
    if self.recomputeKeepingPath and self:IsItineraryValid() then
        self.recomputeKeepingPath = nil
        return
    end
    if not missingCoverage and self.recomputeKeepingDirect and self:IsDirectRouteValid(Position()) then
        self.recomputeKeepingDirect = nil
        return
    end
    local context, destination, start, inputs = self.context, self.destination, self.start, self._routeInputs
    local inCombat = InCombatLockdown and InCombatLockdown()
    local state = (self.waitingData or inCombat) and "waiting_data" or "no_path"
    local data = APR.NavigationData
    if not inCombat and destination and not destination.phaseAgnostic and data and data.GetMapAccessRequirements then
        local requirements = data:GetMapAccessRequirements(destination.uiMapID)
        local phase = requirements and requirements.phase
        if phase and data:GetWorldPhase(phase.group) ~= phase.phase then
            -- A closed destination can also break the diagnostic graph's
            -- walking approaches. Report the gate without publishing a path.
            blockers = { {
                id = "map-access:" .. destination.uiMapID,
                from = start,
                to = destination,
                blockedRequirements = requirements,
            } }
            state = "no_path"
        end
    end
    local approach = self.waypointApproach and self.waypointApproach.reached and self.waypointApproach
    local baselinePending = self._directBaselinePending
    local retainedArrow = state == "waiting_data"
            and not unresolvedSurface
            and not missingCoverage
            and not (self.retainedArrow and self.retainedArrow.serviceWaypoint)
            and self:CaptureRetainedArrow(Position())
        or nil
    self:Cancel("search_failed", retainedArrow ~= nil)
    self.state, self.context, self._routedStepContext, self.destination = state, context, context, destination
    self.start = start
    self.waypointApproach = approach
    if approach and approach.reached then
        self.reason = "waypoint_approach"
    elseif missingCoverage then
        self.reason = "terrain_coverage"
    elseif surfaceOnly and state == "waiting_data" then
        self.reason = unresolvedStart and "terrain_origin" or "terrain_destination"
    end
    self._routeInputs, self.retainedArrow = inputs, retainedArrow
    self._directBaselinePending = baselinePending
    self.blockers = blockers
    self:Notify()
    if state == "no_path" and not (APR.Services and APR.Services:GetStep()) and APR.StartNavigationUnlock then
        APR:StartNavigationUnlock(blockers, context)
    end
end--[[APR_DIAG]]; nav.SearchFailed = APRTrace("APR-Core/features/navigation/controller/NavigationDisplay.lua:350:nav:SearchFailed#13", nav.SearchFailed)--[[/APR_DIAG]]
